@extends('layouts.app') @section('content')<section class="hero"><h1>Track your package</h1><p class="muted">Enter your tracking number to see the latest shipment information.</p><form class="search" method="GET" action="{{ route('tracking.index') }}" data-loading><div class="actions"><input class="input" name="tracking" value="{{ $trackingNumber }}" placeholder="e.g. PKG-20260928-ABC123" required><button class="btn" type="submit">Track Package</button></div></form></section>@if($trackingNumber && !$shipment)<div class="card" style="text-align:center"><h2>No shipment found</h2><p class="muted">Check the tracking number and try again.</p></div>@endif @if($shipment)<div class="grid grid-2"><div class="card"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div><p class="small muted">Tracking number</p><h2>{{ $shipment->tracking_number }}</h2></div><x-shipment-status-badge :status="$shipment->status" /></div><div class="grid grid-2" style="margin-top:20px"><div><span class="small muted">Origin</span><strong>{{ $shipment->origin }}</strong></div><div><span class="small muted">Destination</span><strong>{{ $shipment->destination }}</strong></div><div><span class="small muted">Current location</span><strong>{{ $shipment->current_location ?: 'Not available' }}</strong></div><div><span class="small muted">Last updated</span><strong>{{ $shipment->updated_at->timezone(config('app.display_timezone'))->format('M j, Y g:i A') }}</strong></div></div>@if($shipment->estimated_delivery)<div class="alert" style="margin-top:20px" data-eta="{{ $shipment->estimated_delivery->toIso8601String() }}"><strong>Estimated delivery</strong><div id="eta-countdown"></div><div class="small muted">{{ $shipment->estimated_delivery->timezone(config('app.display_timezone'))->format('M j, Y g:i A') }}</div></div>@endif @if($shipment->status===\App\Enums\ShipmentStatus::DELIVERED)<div class="alert success"><strong>Delivery confirmed</strong><div>Delivered {{ $shipment->d